CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS app_users(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS deriv_connections(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,deriv_account_id TEXT NOT NULL,account_type TEXT NOT NULL CHECK(account_type IN('DEMO','REAL')),currency TEXT NOT NULL,token_ciphertext TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(user_id,deriv_account_id));
CREATE TABLE IF NOT EXISTS trading_sessions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,connection_id UUID NOT NULL REFERENCES deriv_connections(id) ON DELETE RESTRICT,symbol TEXT NOT NULL DEFAULT 'R_100',mode TEXT NOT NULL DEFAULT 'DEMO' CHECK(mode IN('DEMO','LIVE')),status TEXT NOT NULL DEFAULT 'STOPPED',config JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS trade_events(id BIGSERIAL PRIMARY KEY,session_id UUID NOT NULL REFERENCES trading_sessions(id) ON DELETE CASCADE,event_type TEXT NOT NULL,payload JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS trade_records(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),session_id UUID NOT NULL REFERENCES trading_sessions(id) ON DELETE CASCADE,contract_id TEXT NOT NULL UNIQUE,contract_type TEXT NOT NULL,symbol TEXT NOT NULL,stake NUMERIC(20,8) NOT NULL,buy_price NUMERIC(20,8),profit NUMERIC(20,8),status TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),settled_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS sessions_user_idx ON trading_sessions(user_id);
CREATE INDEX IF NOT EXISTS events_session_idx ON trade_events(session_id,created_at DESC);
CREATE INDEX IF NOT EXISTS deriv_connections_user_idx ON deriv_connections(user_id);
